using System;
using System.IO;
using System.Windows;
internal static class CompanionResponsivenessTests {
 internal static void Run(string folder){var store=new Store(Path.Combine(folder,"guide-cache-tests"));var c=new DofusCharacter{id="cache",name="Cache",guide="parcours-exemple",classCode="Sacri"};TougliReader.Cache(store,c.guide,StandaloneTests.Sample);int before=GuideDocumentCache.Parses;var first=QuestProgress.Read(store,c,c.guide);for(int i=0;i<30;i++)if(!Object.ReferenceEquals(first,QuestProgress.Read(store,c,c.guide)))throw new Exception("Document reparsed");if(GuideDocumentCache.Parses-before!=1)throw new Exception("Repeated guide parsing");c.classCode="Iop";if(Object.ReferenceEquals(first,QuestProgress.Read(store,c,c.guide)))throw new Exception("Character branch cache shared");var changed=StandaloneTests.Sample.Replace("Parcours fictif de validation","Parcours actualisé pour le cache");TougliReader.Cache(store,c.guide,changed);File.SetLastWriteTimeUtc(TougliReader.CachePath(store,c.guide),DateTime.UtcNow.AddSeconds(2));if(QuestProgress.Read(store,c,c.guide).Title!="Parcours actualisé pour le cache")throw new Exception("Updated cache ignored");File.Delete(TougliReader.CachePath(store,c.guide));if(QuestProgress.Read(store,c,c.guide)!=null)throw new Exception("Deleted cache reused");var owner=new CompanionWindow(store,true);var dialog=owner.UpdateConfirmationWindow();if(dialog.WindowStyle!=WindowStyle.None||!dialog.AllowsTransparency)throw new Exception("Native update dialog remains");CompanionWindow.RenderPreview(dialog,Path.Combine(folder,"update-confirmation-themed.png"));dialog.Close();owner.Close();File.WriteAllText(Path.Combine(folder,"RESPONSIVENESS_PASS.txt"),"PASS: 30 repeated reads parsed once; class changes, updated and deleted cache; themed update dialog rendered.");}
}
